//! Board snapshot types for JavaScript serialization.
//!
//! These types provide a flat, serializable view of the board state
//! suitable for transmission to JavaScript via serde-wasm-bindgen.
//!
//! All types use primitive types (i64, i32, u32, String) that serialize
//! cleanly to JavaScript numbers and strings.

use cypcb_drc::DrcViolation;
use serde::{Deserialize, Serialize};

/// Complete snapshot of the board state for rendering.
///
/// This is the main type returned by `PcbEngine::get_snapshot()`.
/// It contains all information needed to render the board in JavaScript.
#[derive(Debug, Serialize, Deserialize)]
pub struct BoardSnapshot {
    /// Board information (if a board has been defined).
    pub board: Option<BoardInfo>,
    /// All components on the board.
    pub components: Vec<ComponentInfo>,
    /// All nets and their connections.
    pub nets: Vec<NetInfo>,
    /// DRC violations found after loading.
    pub violations: Vec<ViolationInfo>,
    /// Copper traces (routed connections).
    pub traces: Vec<TraceInfo>,
    /// Vias (layer-to-layer connections).
    pub vias: Vec<ViaInfo>,
    /// Ratsnest lines (unrouted connections).
    pub ratsnest: Vec<RatsnestInfo>,
}

/// A DRC violation for display in the viewer.
///
/// This is a simplified representation of `cypcb_drc::DrcViolation`
/// suitable for JavaScript serialization and rendering.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ViolationInfo {
    /// Violation type (clearance, drill_size, unconnected_pin, etc.)
    pub kind: String,
    /// Board location X in nanometers.
    pub x_nm: i64,
    /// Board location Y in nanometers.
    pub y_nm: i64,
    /// Human-readable message.
    pub message: String,
}

impl ViolationInfo {
    /// Create a ViolationInfo from a DrcViolation.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::{DrcViolation, ViolationKind};
    /// use cypcb_core::Point;
    /// use cypcb_world::Entity;
    /// use cypcb_render::ViolationInfo;
    ///
    /// let v = DrcViolation::unconnected_pin(
    ///     Entity::from_raw(1),
    ///     "1",
    ///     "R1",
    ///     Point::from_mm(10.0, 20.0),
    /// );
    /// let info = ViolationInfo::from_drc(&v);
    /// assert_eq!(info.kind, "unconnected-pin");
    /// assert!(info.message.contains("R1.1"));
    /// ```
    pub fn from_drc(v: &DrcViolation) -> Self {
        ViolationInfo {
            kind: format!("{}", v.kind),
            x_nm: v.location.x.0,
            y_nm: v.location.y.0,
            message: v.message.clone(),
        }
    }
}

/// Board-level information.
#[derive(Debug, Serialize, Deserialize)]
pub struct BoardInfo {
    /// Board name/identifier.
    pub name: String,
    /// Board width in nanometers.
    pub width_nm: i64,
    /// Board height in nanometers.
    pub height_nm: i64,
    /// Number of copper layers.
    pub layer_count: u8,
}

/// Component information for rendering.
#[derive(Debug, Serialize, Deserialize)]
pub struct ComponentInfo {
    /// Reference designator (R1, C1, U1, etc.).
    pub refdes: String,
    /// Component value (10k, 100nF, etc.).
    pub value: String,
    /// X position in nanometers.
    pub x_nm: i64,
    /// Y position in nanometers.
    pub y_nm: i64,
    /// Rotation in millidegrees (0-359999).
    pub rotation_mdeg: i32,
    /// Footprint name/identifier.
    pub footprint: String,
    /// Pad definitions from the footprint.
    pub pads: Vec<PadInfo>,
}

/// Pad information for rendering.
///
/// Positions are relative to the component origin.
#[derive(Debug, Serialize, Deserialize)]
pub struct PadInfo {
    /// Pad number/name (e.g., "1", "2", "A1", "VCC").
    pub number: String,
    /// X position relative to component origin, in nanometers.
    pub x_nm: i64,
    /// Y position relative to component origin, in nanometers.
    pub y_nm: i64,
    /// Pad width in nanometers.
    pub width_nm: i64,
    /// Pad height in nanometers.
    pub height_nm: i64,
    /// Shape as string: "circle", "rect", "roundrect", "oblong".
    pub shape: String,
    /// Copper layer bit mask (bit 0 = top, bit 1 = bottom, bits 2-31 = inner).
    pub layer_mask: u32,
    /// Drill diameter in nanometers (None for SMD pads).
    pub drill_nm: Option<i64>,
}

/// Net information.
#[derive(Debug, Serialize, Deserialize)]
pub struct NetInfo {
    /// Net name.
    pub name: String,
    /// Net ID (internal identifier).
    pub id: u32,
    /// All pin connections to this net.
    pub connections: Vec<PinRef>,
}

/// Reference to a component pin.
#[derive(Debug, Serialize, Deserialize)]
pub struct PinRef {
    /// Component reference designator.
    pub component: String,
    /// Pin number/name.
    pub pin: String,
}

/// A single segment of a trace (line from start to end).
///
/// TraceSegmentInfo is the JavaScript-serializable version of
/// `cypcb_world::components::trace::TraceSegment`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TraceSegmentInfo {
    /// Start X coordinate in nanometers.
    pub start_x: f64,
    /// Start Y coordinate in nanometers.
    pub start_y: f64,
    /// End X coordinate in nanometers.
    pub end_x: f64,
    /// End Y coordinate in nanometers.
    pub end_y: f64,
}

/// Trace information for rendering.
///
/// Represents a copper trace as a polyline with a given width.
/// Used by the JavaScript renderer to draw routed connections.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TraceInfo {
    /// The polyline path as a vector of segments.
    pub segments: Vec<TraceSegmentInfo>,
    /// Trace width in nanometers.
    pub width: f64,
    /// Layer name ("Top" or "Bottom").
    pub layer: String,
    /// Net name this trace belongs to.
    pub net_name: String,
    /// Whether this trace is locked (manual, not to be modified).
    pub locked: bool,
}

/// Via information for rendering.
///
/// Represents a plated through-hole connecting copper layers.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ViaInfo {
    /// Center X coordinate in nanometers.
    pub x: f64,
    /// Center Y coordinate in nanometers.
    pub y: f64,
    /// Drill hole diameter in nanometers.
    pub drill: f64,
    /// Outer diameter (copper ring) in nanometers.
    pub outer_diameter: f64,
    /// Net name this via belongs to.
    pub net_name: String,
}

/// Ratsnest line information for rendering.
///
/// Represents an unrouted connection between two pins.
/// Shown as a thin line to indicate what still needs routing.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RatsnestInfo {
    /// Start X coordinate in nanometers.
    pub start_x: f64,
    /// Start Y coordinate in nanometers.
    pub start_y: f64,
    /// End X coordinate in nanometers.
    pub end_x: f64,
    /// End Y coordinate in nanometers.
    pub end_y: f64,
    /// Net name this connection belongs to.
    pub net_name: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_board_snapshot_serializes() {
        let snapshot = BoardSnapshot {
            board: Some(BoardInfo {
                name: "Test".to_string(),
                width_nm: 100_000_000,
                height_nm: 80_000_000,
                layer_count: 2,
            }),
            components: vec![ComponentInfo {
                refdes: "R1".to_string(),
                value: "10k".to_string(),
                x_nm: 10_000_000,
                y_nm: 20_000_000,
                rotation_mdeg: 0,
                footprint: "0402".to_string(),
                pads: vec![
                    PadInfo {
                        number: "1".to_string(),
                        x_nm: -500_000,
                        y_nm: 0,
                        width_nm: 600_000,
                        height_nm: 500_000,
                        shape: "rect".to_string(),
                        layer_mask: 1,
                        drill_nm: None,
                    },
                    PadInfo {
                        number: "2".to_string(),
                        x_nm: 500_000,
                        y_nm: 0,
                        width_nm: 600_000,
                        height_nm: 500_000,
                        shape: "rect".to_string(),
                        layer_mask: 1,
                        drill_nm: None,
                    },
                ],
            }],
            nets: vec![NetInfo {
                name: "VCC".to_string(),
                id: 0,
                connections: vec![PinRef {
                    component: "R1".to_string(),
                    pin: "1".to_string(),
                }],
            }],
            violations: vec![],
            traces: vec![],
            vias: vec![],
            ratsnest: vec![],
        };

        // Verify it can serialize to JSON (serde-wasm-bindgen uses serde)
        let json = serde_json::to_string(&snapshot).unwrap();
        assert!(json.contains("\"name\":\"Test\""));
        assert!(json.contains("\"refdes\":\"R1\""));
        assert!(json.contains("\"name\":\"VCC\""));
        assert!(json.contains("\"violations\":[]"));
        assert!(json.contains("\"traces\":[]"));
        assert!(json.contains("\"vias\":[]"));
        assert!(json.contains("\"ratsnest\":[]"));
    }

    #[test]
    fn test_violation_info_from_drc() {
        use cypcb_core::Point;
        use cypcb_world::Entity;

        let violation = cypcb_drc::DrcViolation::unconnected_pin(
            Entity::from_raw(1),
            "1",
            "R1",
            Point::from_mm(10.0, 20.0),
        );
        let info = ViolationInfo::from_drc(&violation);

        assert_eq!(info.kind, "unconnected-pin");
        assert_eq!(info.x_nm, 10_000_000);
        assert_eq!(info.y_nm, 20_000_000);
        assert!(info.message.contains("R1.1"));
    }

    #[test]
    fn test_violation_info_serializes() {
        let violation = ViolationInfo {
            kind: "clearance".to_string(),
            x_nm: 5_000_000,
            y_nm: 10_000_000,
            message: "Clearance violation: 0.10mm actual, 0.15mm required".to_string(),
        };

        let json = serde_json::to_string(&violation).unwrap();
        assert!(json.contains("\"kind\":\"clearance\""));
        assert!(json.contains("\"x_nm\":5000000"));
        assert!(json.contains("\"message\""));
    }

    #[test]
    fn test_trace_info_serializes() {
        let trace = TraceInfo {
            segments: vec![
                TraceSegmentInfo {
                    start_x: 0.0,
                    start_y: 0.0,
                    end_x: 10_000_000.0,
                    end_y: 0.0,
                },
                TraceSegmentInfo {
                    start_x: 10_000_000.0,
                    start_y: 0.0,
                    end_x: 10_000_000.0,
                    end_y: 5_000_000.0,
                },
            ],
            width: 200_000.0, // 0.2mm
            layer: "Top".to_string(),
            net_name: "VCC".to_string(),
            locked: true,
        };

        let json = serde_json::to_string(&trace).unwrap();
        assert!(json.contains("\"layer\":\"Top\""));
        assert!(json.contains("\"net_name\":\"VCC\""));
        assert!(json.contains("\"locked\":true"));
        assert!(json.contains("\"width\":200000"));
        assert!(json.contains("\"segments\""));
    }

    #[test]
    fn test_via_info_serializes() {
        let via = ViaInfo {
            x: 5_000_000.0,
            y: 10_000_000.0,
            drill: 300_000.0,       // 0.3mm
            outer_diameter: 600_000.0, // 0.6mm
            net_name: "GND".to_string(),
        };

        let json = serde_json::to_string(&via).unwrap();
        assert!(json.contains("\"x\":5000000"));
        assert!(json.contains("\"y\":10000000"));
        assert!(json.contains("\"drill\":300000"));
        assert!(json.contains("\"outer_diameter\":600000"));
        assert!(json.contains("\"net_name\":\"GND\""));
    }

    #[test]
    fn test_ratsnest_info_serializes() {
        let ratsnest = RatsnestInfo {
            start_x: 0.0,
            start_y: 0.0,
            end_x: 20_000_000.0,
            end_y: 15_000_000.0,
            net_name: "SIGNAL".to_string(),
        };

        let json = serde_json::to_string(&ratsnest).unwrap();
        assert!(json.contains("\"start_x\":0"));
        assert!(json.contains("\"start_y\":0"));
        assert!(json.contains("\"end_x\":20000000"));
        assert!(json.contains("\"end_y\":15000000"));
        assert!(json.contains("\"net_name\":\"SIGNAL\""));
    }

    #[test]
    fn test_snapshot_with_traces() {
        let snapshot = BoardSnapshot {
            board: Some(BoardInfo {
                name: "TraceTest".to_string(),
                width_nm: 50_000_000,
                height_nm: 30_000_000,
                layer_count: 2,
            }),
            components: vec![],
            nets: vec![],
            violations: vec![],
            traces: vec![TraceInfo {
                segments: vec![TraceSegmentInfo {
                    start_x: 5_000_000.0,
                    start_y: 5_000_000.0,
                    end_x: 25_000_000.0,
                    end_y: 5_000_000.0,
                }],
                width: 250_000.0,
                layer: "Top".to_string(),
                net_name: "VCC".to_string(),
                locked: false,
            }],
            vias: vec![ViaInfo {
                x: 25_000_000.0,
                y: 5_000_000.0,
                drill: 300_000.0,
                outer_diameter: 600_000.0,
                net_name: "VCC".to_string(),
            }],
            ratsnest: vec![],
        };

        let json = serde_json::to_string(&snapshot).unwrap();
        assert!(json.contains("\"traces\""));
        assert!(json.contains("\"vias\""));
        assert!(json.contains("\"VCC\""));
    }
}

//! Spatial indexing for efficient region queries.
//!
//! Uses an R*-tree to enable O(log n) queries for:
//! - Finding all entities in a rectangular region
//! - Finding entities at a specific point
//! - Finding entities that might overlap with a given entity
//!
//! This is essential for:
//! - DRC (Design Rule Check) - finding nearby objects to check clearances
//! - Rendering - only drawing visible objects
//! - Selection - finding objects under cursor

use bevy_ecs::prelude::*;
use rstar::{RTree, RTreeObject, AABB};

use cypcb_core::Point;

/// An entry in the spatial index.
///
/// Associates an entity with its bounding box and layer information.
/// The layer mask allows filtering queries by copper layer.
#[derive(Debug, Clone)]
pub struct SpatialEntry {
    /// The ECS entity this entry represents.
    pub entity: Entity,
    /// The axis-aligned bounding box in nanometers.
    pub envelope: AABB<[i64; 2]>,
    /// Bit mask of layers this entity occupies (bit 0 = layer 0, etc.).
    pub layer_mask: u32,
}

impl SpatialEntry {
    /// Create a new spatial entry.
    ///
    /// # Arguments
    ///
    /// * `entity` - The ECS entity
    /// * `min` - Minimum corner of bounding box
    /// * `max` - Maximum corner of bounding box
    /// * `layer_mask` - Bit mask of occupied layers
    ///
    /// # Examples
    ///
    /// ```
    /// use bevy_ecs::prelude::*;
    /// use cypcb_world::SpatialEntry;
    /// use cypcb_core::Point;
    ///
    /// // Create an entry for a component on top layer only
    /// let entry = SpatialEntry::new(
    ///     Entity::from_raw(0),
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(10.0, 10.0),
    ///     0b01,  // Top layer only
    /// );
    /// ```
    pub fn new(entity: Entity, min: Point, max: Point, layer_mask: u32) -> Self {
        SpatialEntry {
            entity,
            envelope: AABB::from_corners([min.x.0, min.y.0], [max.x.0, max.y.0]),
            layer_mask,
        }
    }

    /// Create an entry from raw coordinates.
    pub fn from_raw(entity: Entity, min_x: i64, min_y: i64, max_x: i64, max_y: i64, layer_mask: u32) -> Self {
        SpatialEntry {
            entity,
            envelope: AABB::from_corners([min_x, min_y], [max_x, max_y]),
            layer_mask,
        }
    }

    /// Check if this entry overlaps with a specific layer.
    #[inline]
    pub fn on_layer(&self, layer: u8) -> bool {
        self.layer_mask & (1 << layer) != 0
    }

    /// Check if this entry shares any layers with the given mask.
    #[inline]
    pub fn layers_overlap(&self, mask: u32) -> bool {
        self.layer_mask & mask != 0
    }
}

impl RTreeObject for SpatialEntry {
    type Envelope = AABB<[i64; 2]>;

    fn envelope(&self) -> Self::Envelope {
        self.envelope
    }
}

/// R*-tree spatial index for efficient region queries.
///
/// Wraps an rstar `RTree` to provide O(log n) spatial queries.
/// The index is rebuilt after batch updates rather than supporting
/// incremental insertion, which is more efficient for the typical
/// "parse file, build world" workflow.
///
/// # Examples
///
/// ```
/// use bevy_ecs::prelude::*;
/// use cypcb_world::{SpatialIndex, SpatialEntry};
/// use cypcb_core::Point;
///
/// let mut index = SpatialIndex::new();
///
/// // Create some entries
/// let entries = vec![
///     SpatialEntry::new(
///         Entity::from_raw(0),
///         Point::from_mm(0.0, 0.0),
///         Point::from_mm(10.0, 10.0),
///         0b01,
///     ),
///     SpatialEntry::new(
///         Entity::from_raw(1),
///         Point::from_mm(5.0, 5.0),
///         Point::from_mm(15.0, 15.0),
///         0b01,
///     ),
/// ];
///
/// // Bulk load for efficiency
/// index.rebuild(entries);
///
/// // Query a region
/// let found: Vec<_> = index.query_region(
///     Point::from_mm(4.0, 4.0),
///     Point::from_mm(6.0, 6.0),
/// ).collect();
/// assert_eq!(found.len(), 2); // Both entries overlap
/// ```
#[derive(Resource, Default)]
pub struct SpatialIndex {
    tree: RTree<SpatialEntry>,
}

impl SpatialIndex {
    /// Create an empty spatial index.
    #[inline]
    pub fn new() -> Self {
        SpatialIndex {
            tree: RTree::new(),
        }
    }

    /// Query all entities whose bounding boxes intersect the given region.
    ///
    /// Returns an iterator over entities (not entries) for convenience.
    ///
    /// # Arguments
    ///
    /// * `min` - Minimum corner of query region
    /// * `max` - Maximum corner of query region
    ///
    /// # Examples
    ///
    /// ```
    /// use bevy_ecs::prelude::*;
    /// use cypcb_world::{SpatialIndex, SpatialEntry};
    /// use cypcb_core::Point;
    ///
    /// let mut index = SpatialIndex::new();
    /// index.rebuild(vec![
    ///     SpatialEntry::new(Entity::from_raw(0), Point::from_mm(0.0, 0.0), Point::from_mm(10.0, 10.0), 1),
    /// ]);
    ///
    /// let found: Vec<_> = index.query_region(Point::from_mm(5.0, 5.0), Point::from_mm(15.0, 15.0)).collect();
    /// assert_eq!(found.len(), 1);
    /// ```
    pub fn query_region(&self, min: Point, max: Point) -> impl Iterator<Item = Entity> + '_ {
        let envelope = AABB::from_corners([min.x.0, min.y.0], [max.x.0, max.y.0]);
        self.tree
            .locate_in_envelope_intersecting(&envelope)
            .map(|e| e.entity)
    }

    /// Query all entries (with full metadata) in a region.
    ///
    /// Use this when you need layer information or bounding boxes.
    pub fn query_region_entries(&self, min: Point, max: Point) -> impl Iterator<Item = &SpatialEntry> {
        let envelope = AABB::from_corners([min.x.0, min.y.0], [max.x.0, max.y.0]);
        self.tree.locate_in_envelope_intersecting(&envelope)
    }

    /// Query entities at a specific point.
    ///
    /// Returns all entities whose bounding box contains the point.
    pub fn query_point(&self, point: Point) -> impl Iterator<Item = Entity> + '_ {
        let p = [point.x.0, point.y.0];
        let envelope = AABB::from_point(p);
        self.tree
            .locate_in_envelope_intersecting(&envelope)
            .map(|e| e.entity)
    }

    /// Query entities at a point, filtered by layer.
    ///
    /// # Arguments
    ///
    /// * `point` - The query point
    /// * `layer_mask` - Bit mask of layers to include
    pub fn query_point_on_layers(
        &self,
        point: Point,
        layer_mask: u32,
    ) -> impl Iterator<Item = Entity> + '_ {
        let p = [point.x.0, point.y.0];
        let envelope = AABB::from_point(p);
        self.tree
            .locate_in_envelope_intersecting(&envelope)
            .filter(move |e| e.layers_overlap(layer_mask))
            .map(|e| e.entity)
    }

    /// Query entities in a region, filtered by layer.
    ///
    /// # Arguments
    ///
    /// * `min` - Minimum corner of query region
    /// * `max` - Maximum corner of query region
    /// * `layer_mask` - Bit mask of layers to include
    pub fn query_region_on_layers(
        &self,
        min: Point,
        max: Point,
        layer_mask: u32,
    ) -> impl Iterator<Item = Entity> + '_ {
        let envelope = AABB::from_corners([min.x.0, min.y.0], [max.x.0, max.y.0]);
        self.tree
            .locate_in_envelope_intersecting(&envelope)
            .filter(move |e| e.layers_overlap(layer_mask))
            .map(|e| e.entity)
    }

    /// Rebuild the spatial index with new entries.
    ///
    /// Uses bulk loading for optimal tree structure.
    /// This is more efficient than incremental insertion for large batches.
    ///
    /// # Arguments
    ///
    /// * `entries` - Vector of spatial entries to index
    pub fn rebuild(&mut self, entries: Vec<SpatialEntry>) {
        self.tree = RTree::bulk_load(entries);
    }

    /// Clear the spatial index.
    pub fn clear(&mut self) {
        self.tree = RTree::new();
    }

    /// Check if the index is empty.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.tree.size() == 0
    }

    /// Get the number of entries in the index.
    #[inline]
    pub fn len(&self) -> usize {
        self.tree.size()
    }

    /// Iterate over all entries in the index.
    pub fn iter(&self) -> impl Iterator<Item = &SpatialEntry> {
        self.tree.iter()
    }
}

impl std::fmt::Debug for SpatialIndex {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SpatialIndex")
            .field("entries", &self.tree.size())
            .finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn make_entry(id: u32, min_mm: (f64, f64), max_mm: (f64, f64), layers: u32) -> SpatialEntry {
        SpatialEntry::new(
            Entity::from_raw(id),
            Point::from_mm(min_mm.0, min_mm.1),
            Point::from_mm(max_mm.0, max_mm.1),
            layers,
        )
    }

    #[test]
    fn test_empty_index() {
        let index = SpatialIndex::new();
        assert!(index.is_empty());
        assert_eq!(index.len(), 0);
    }

    #[test]
    fn test_rebuild_and_len() {
        let mut index = SpatialIndex::new();
        let entries = vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (20.0, 20.0), (30.0, 30.0), 1),
        ];
        index.rebuild(entries);

        assert!(!index.is_empty());
        assert_eq!(index.len(), 2);
    }

    #[test]
    fn test_query_region_finds_intersecting() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (5.0, 5.0), (15.0, 15.0), 1),
            make_entry(2, (100.0, 100.0), (110.0, 110.0), 1),
        ]);

        // Query overlapping region - should find entries 0 and 1
        let found: Vec<_> = index
            .query_region(Point::from_mm(4.0, 4.0), Point::from_mm(6.0, 6.0))
            .collect();
        assert_eq!(found.len(), 2);

        // Query region only overlapping entry 2
        let found: Vec<_> = index
            .query_region(Point::from_mm(105.0, 105.0), Point::from_mm(106.0, 106.0))
            .collect();
        assert_eq!(found.len(), 1);
        assert_eq!(found[0], Entity::from_raw(2));
    }

    #[test]
    fn test_query_region_no_match() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![make_entry(0, (0.0, 0.0), (10.0, 10.0), 1)]);

        let found: Vec<_> = index
            .query_region(Point::from_mm(50.0, 50.0), Point::from_mm(60.0, 60.0))
            .collect();
        assert!(found.is_empty());
    }

    #[test]
    fn test_query_point() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (5.0, 5.0), (15.0, 15.0), 1),
        ]);

        // Point inside only entry 0
        let found: Vec<_> = index.query_point(Point::from_mm(2.0, 2.0)).collect();
        assert_eq!(found.len(), 1);
        assert_eq!(found[0], Entity::from_raw(0));

        // Point inside both entries
        let found: Vec<_> = index.query_point(Point::from_mm(7.0, 7.0)).collect();
        assert_eq!(found.len(), 2);
    }

    #[test]
    fn test_layer_filtering() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 0b01), // Top only
            make_entry(1, (0.0, 0.0), (10.0, 10.0), 0b10), // Bottom only
            make_entry(2, (0.0, 0.0), (10.0, 10.0), 0b11), // Both
        ]);

        // Query top layer only
        let found: Vec<_> = index
            .query_region_on_layers(
                Point::from_mm(0.0, 0.0),
                Point::from_mm(10.0, 10.0),
                0b01,
            )
            .collect();
        assert_eq!(found.len(), 2); // Entries 0 and 2

        // Query bottom layer only
        let found: Vec<_> = index
            .query_region_on_layers(
                Point::from_mm(0.0, 0.0),
                Point::from_mm(10.0, 10.0),
                0b10,
            )
            .collect();
        assert_eq!(found.len(), 2); // Entries 1 and 2
    }

    #[test]
    fn test_entry_layer_methods() {
        let entry = make_entry(0, (0.0, 0.0), (10.0, 10.0), 0b101); // Layers 0 and 2

        assert!(entry.on_layer(0));
        assert!(!entry.on_layer(1));
        assert!(entry.on_layer(2));

        assert!(entry.layers_overlap(0b001));
        assert!(!entry.layers_overlap(0b010));
        assert!(entry.layers_overlap(0b111));
    }

    #[test]
    fn test_clear() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![make_entry(0, (0.0, 0.0), (10.0, 10.0), 1)]);
        assert!(!index.is_empty());

        index.clear();
        assert!(index.is_empty());
    }

    #[test]
    fn test_iter() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (20.0, 20.0), (30.0, 30.0), 1),
        ]);

        let entries: Vec<_> = index.iter().collect();
        assert_eq!(entries.len(), 2);
    }
}

//! BoardWorld - High-level API for PCB board entities.
//!
//! Provides a clean wrapper around bevy_ecs::World with PCB-specific
//! operations for creating boards, spawning components, and querying.
//!
//! # Example
//!
//! ```
//! use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
//! use cypcb_core::Nm;
//!
//! // Create a new board world
//! let mut world = BoardWorld::new();
//!
//! // Set up the board
//! let board = world.set_board("MyBoard".to_string(), (Nm::from_mm(100.0), Nm::from_mm(80.0)), 4);
//!
//! // Intern net names
//! let vcc = world.intern_net("VCC");
//! let gnd = world.intern_net("GND");
//!
//! // Spawn components
//! let r1 = world.spawn_component(
//!     RefDes::new("R1"),
//!     Value::new("10k"),
//!     Position::from_mm(10.0, 20.0),
//!     Rotation::ZERO,
//!     FootprintRef::new("0402"),
//!     NetConnections::new(),
//! );
//!
//! // Query the world
//! assert_eq!(world.component_count(), 1);
//! ```

use bevy_ecs::prelude::*;

use cypcb_core::{Nm, Point, Rect};

use crate::components::*;
use crate::registry::NetRegistry;
use crate::spatial::{SpatialEntry, SpatialIndex};

/// High-level wrapper around bevy_ecs::World for PCB board operations.
///
/// BoardWorld provides a clean, type-safe API for:
/// - Creating and configuring the board
/// - Spawning component entities
/// - Interning net names
/// - Spatial queries
/// - Direct ECS access when needed
///
/// # Architecture
///
/// Internally uses bevy_ecs::World with two resources:
/// - [`NetRegistry`]: For interning net names to integer IDs
/// - [`SpatialIndex`]: For efficient region-based queries
///
/// # Example
///
/// ```
/// use cypcb_world::BoardWorld;
/// use cypcb_core::Nm;
///
/// let mut world = BoardWorld::new();
///
/// // Create a 100x80mm 4-layer board
/// world.set_board("MyPCB".to_string(), (Nm::from_mm(100.0), Nm::from_mm(80.0)), 4);
///
/// // Get board info
/// if let Some((size, layers)) = world.board_info() {
///     println!("Board: {}x{}, {} layers", size.width, size.height, layers.count);
/// }
/// ```
pub struct BoardWorld {
    /// The underlying bevy_ecs World.
    world: World,
    /// Entity ID of the board (if set).
    board_entity: Option<Entity>,
}

impl BoardWorld {
    /// Create a new empty BoardWorld.
    ///
    /// Initializes the ECS world with:
    /// - Empty [`SpatialIndex`] resource
    /// - Empty [`NetRegistry`] resource
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let world = BoardWorld::new();
    /// assert!(world.is_empty());
    /// ```
    pub fn new() -> Self {
        let mut world = World::new();
        world.insert_resource(SpatialIndex::new());
        world.insert_resource(NetRegistry::new());
        BoardWorld {
            world,
            board_entity: None,
        }
    }

    // ========================================================================
    // Board Management
    // ========================================================================

    /// Set the board properties, creating or updating the board entity.
    ///
    /// There can only be one board entity. Calling this multiple times
    /// will update the existing board entity.
    ///
    /// # Arguments
    ///
    /// * `name` - Board name/identifier
    /// * `size` - Board dimensions as (width, height) in nanometers
    /// * `layers` - Number of copper layers (2-32)
    ///
    /// # Returns
    ///
    /// The board entity ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    /// use cypcb_core::Nm;
    ///
    /// let mut world = BoardWorld::new();
    /// let board = world.set_board(
    ///     "TestBoard".to_string(),
    ///     (Nm::from_mm(100.0), Nm::from_mm(80.0)),
    ///     4,
    /// );
    /// ```
    pub fn set_board(&mut self, name: String, size: (Nm, Nm), layers: u8) -> Entity {
        let board_size = BoardSize::new(size.0, size.1);
        let layer_stack = LayerStack::new(layers);
        let name_component = crate::components::metadata::Name(name);

        if let Some(entity) = self.board_entity {
            // Update existing board
            let mut entity_mut = self.world.entity_mut(entity);
            entity_mut.insert((Board, board_size, layer_stack, name_component));
            entity
        } else {
            // Create new board
            let entity = self
                .world
                .spawn((Board, board_size, layer_stack, name_component))
                .id();
            self.board_entity = Some(entity);
            entity
        }
    }

    /// Get the board entity ID if one has been set.
    pub fn board_entity(&self) -> Option<Entity> {
        self.board_entity
    }

    /// Get board size and layer stack if a board has been set.
    ///
    /// # Returns
    ///
    /// Tuple of (BoardSize, LayerStack) if board exists, None otherwise.
    pub fn board_info(&self) -> Option<(BoardSize, LayerStack)> {
        let entity = self.board_entity?;
        let size = self.world.get::<BoardSize>(entity)?;
        let layers = self.world.get::<LayerStack>(entity)?;
        Some((*size, *layers))
    }

    /// Get the board name if one has been set.
    pub fn board_name(&self) -> Option<&str> {
        let entity = self.board_entity?;
        self.world
            .get::<crate::components::metadata::Name>(entity)
            .map(|n| n.0.as_str())
    }

    // ========================================================================
    // Component Spawning
    // ========================================================================

    /// Spawn a new component entity.
    ///
    /// # Arguments
    ///
    /// * `refdes` - Reference designator (R1, C1, U1, etc.)
    /// * `value` - Component value (10k, 100nF, etc.)
    /// * `position` - Position on board
    /// * `rotation` - Rotation angle
    /// * `footprint` - Footprint reference
    /// * `nets` - Net connections for each pin
    ///
    /// # Returns
    ///
    /// The spawned entity ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    /// ```
    pub fn spawn_component(
        &mut self,
        refdes: RefDes,
        value: Value,
        position: Position,
        rotation: Rotation,
        footprint: FootprintRef,
        nets: NetConnections,
    ) -> Entity {
        self.world
            .spawn((refdes, value, position, rotation, footprint, nets))
            .id()
    }

    /// Spawn a component with a source span for error reporting.
    ///
    /// Same as [`spawn_component`](Self::spawn_component) but also attaches
    /// a [`SourceSpan`] for linking back to source file locations.
    pub fn spawn_component_with_span(
        &mut self,
        refdes: RefDes,
        value: Value,
        position: Position,
        rotation: Rotation,
        footprint: FootprintRef,
        nets: NetConnections,
        span: SourceSpan,
    ) -> Entity {
        self.world
            .spawn((refdes, value, position, rotation, footprint, nets, span))
            .id()
    }

    /// Spawn an entity with arbitrary components.
    ///
    /// Use this for custom entity types not covered by [`spawn_component`](Self::spawn_component).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Position};
    ///
    /// let mut world = BoardWorld::new();
    /// let entity = world.spawn_entity((
    ///     RefDes::new("J1"),
    ///     Position::from_mm(5.0, 5.0),
    /// ));
    /// ```
    pub fn spawn_entity<B: Bundle>(&mut self, bundle: B) -> Entity {
        self.world.spawn(bundle).id()
    }

    // ========================================================================
    // Net Registry
    // ========================================================================

    /// Intern a net name, returning its unique NetId.
    ///
    /// If the name has already been interned, returns the existing ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let mut world = BoardWorld::new();
    /// let vcc = world.intern_net("VCC");
    /// let vcc2 = world.intern_net("VCC");
    /// assert_eq!(vcc, vcc2); // Same ID
    /// ```
    pub fn intern_net(&mut self, name: &str) -> NetId {
        self.world.resource_mut::<NetRegistry>().intern(name)
    }

    /// Get the name for a NetId.
    ///
    /// Returns None if the ID is invalid.
    pub fn net_name(&self, id: NetId) -> Option<&str> {
        self.world.resource::<NetRegistry>().name(id)
    }

    /// Look up a NetId by name without interning.
    ///
    /// Returns None if the name has not been interned.
    pub fn get_net(&self, name: &str) -> Option<NetId> {
        self.world.resource::<NetRegistry>().get(name)
    }

    /// Get the number of interned nets.
    pub fn net_count(&self) -> usize {
        self.world.resource::<NetRegistry>().len()
    }

    /// Iterate over all interned nets.
    pub fn nets(&self) -> impl Iterator<Item = (NetId, &str)> {
        self.world.resource::<NetRegistry>().iter()
    }

    // ========================================================================
    // Spatial Index
    // ========================================================================

    /// Get a reference to the spatial index.
    ///
    /// Use this for direct spatial queries, iteration, or DRC checks.
    ///
    /// # Note
    ///
    /// The spatial index must be rebuilt after component changes
    /// using [`rebuild_spatial_index`](Self::rebuild_spatial_index).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let world = BoardWorld::new();
    /// let spatial = world.spatial();
    /// assert!(spatial.is_empty());
    /// ```
    pub fn spatial(&self) -> &SpatialIndex {
        self.world.resource::<SpatialIndex>()
    }

    /// Rebuild the spatial index from current component positions.
    ///
    /// Call this after modifying component positions or spawning
    /// components to update the spatial index for efficient queries.
    ///
    /// # Arguments
    ///
    /// * `footprint_bounds` - Function to get bounds for a footprint name.
    ///   Used to calculate entity bounding boxes.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    /// use cypcb_core::{Nm, Rect, Point};
    ///
    /// let mut world = BoardWorld::new();
    /// // ... spawn components ...
    ///
    /// // Rebuild with simple bounds
    /// world.rebuild_spatial_index(|_| Rect::from_center_size(
    ///     Point::ORIGIN,
    ///     (Nm::from_mm(1.0), Nm::from_mm(1.0)),
    /// ));
    /// ```
    pub fn rebuild_spatial_index<F>(&mut self, footprint_bounds: F)
    where
        F: Fn(&str) -> Rect,
    {
        let mut entries = Vec::new();

        // Query all positioned entities with footprints
        let mut query = self
            .world
            .query::<(Entity, &Position, &FootprintRef)>();

        for (entity, position, footprint) in query.iter(&self.world) {
            let bounds = footprint_bounds(footprint.as_str());
            let pos = position.0;

            // Translate bounds by position
            let min = Point::new(
                Nm(pos.x.0 + bounds.min.x.0),
                Nm(pos.y.0 + bounds.min.y.0),
            );
            let max = Point::new(
                Nm(pos.x.0 + bounds.max.x.0),
                Nm(pos.y.0 + bounds.max.y.0),
            );

            // Default to all layers for now (could be refined with pad layer info)
            let layer_mask = 0xFFFFFFFF;

            entries.push(SpatialEntry::new(entity, min, max, layer_mask));
        }

        self.world.resource_mut::<SpatialIndex>().rebuild(entries);
    }

    /// Query entities in a rectangular region.
    ///
    /// Returns all entities whose bounding boxes intersect the given bounds.
    ///
    /// # Note
    ///
    /// The spatial index must be rebuilt after component changes
    /// using [`rebuild_spatial_index`](Self::rebuild_spatial_index).
    pub fn query_region(&self, bounds: Rect) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_region(bounds.min, bounds.max)
            .collect()
    }

    /// Query entities at a specific point.
    ///
    /// Returns all entities whose bounding boxes contain the point.
    pub fn query_point(&self, point: Point) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_point(point)
            .collect()
    }

    /// Query entities in a region, filtered by layer.
    ///
    /// # Arguments
    ///
    /// * `bounds` - The query region
    /// * `layer_mask` - Bit mask of layers to include
    pub fn query_region_on_layers(&self, bounds: Rect, layer_mask: u32) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_region_on_layers(bounds.min, bounds.max, layer_mask)
            .collect()
    }

    // ========================================================================
    // Entity Queries
    // ========================================================================

    /// Get the number of component entities (excluding board).
    pub fn component_count(&mut self) -> usize {
        let mut query = self.world.query::<&RefDes>();
        query.iter(&self.world).count()
    }

    /// Check if the world is empty (no entities).
    pub fn is_empty(&self) -> bool {
        self.world.entities().len() == 0
    }

    /// Get a component from an entity.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    ///
    /// let refdes = world.get::<RefDes>(r1);
    /// assert_eq!(refdes.map(|r| r.as_str()), Some("R1"));
    /// ```
    pub fn get<T: Component>(&self, entity: Entity) -> Option<&T> {
        self.world.get::<T>(entity)
    }

    /// Get a mutable reference to a component.
    pub fn get_mut<T: Component>(&mut self, entity: Entity) -> Option<Mut<'_, T>> {
        self.world.get_mut::<T>(entity)
    }

    /// Check if an entity has a specific component.
    pub fn has<T: Component>(&self, entity: Entity) -> bool {
        self.world.get::<T>(entity).is_some()
    }

    /// Find an entity by its reference designator.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    ///
    /// assert_eq!(world.find_by_refdes("R1"), Some(r1));
    /// assert_eq!(world.find_by_refdes("R2"), None);
    /// ```
    pub fn find_by_refdes(&mut self, refdes: &str) -> Option<Entity> {
        let mut query = self.world.query::<(Entity, &RefDes)>();
        query
            .iter(&self.world)
            .find(|(_, r)| r.as_str() == refdes)
            .map(|(e, _)| e)
    }

    /// Iterate over all components (entities with RefDes).
    ///
    /// Returns a vector of (Entity, RefDes clone, Position clone) tuples.
    /// Uses clones to avoid lifetime issues with the query.
    pub fn components(&mut self) -> Vec<(Entity, RefDes, Position)> {
        let mut query = self.world.query::<(Entity, &RefDes, &Position)>();
        query
            .iter(&self.world)
            .map(|(e, r, p)| (e, r.clone(), *p))
            .collect()
    }

    /// Iterate over all zones.
    ///
    /// Returns a vector of (Entity, Zone clone) tuples.
    /// Uses clones to avoid lifetime issues with the query.
    pub fn zones(&mut self) -> Vec<(Entity, Zone)> {
        let mut query = self.world.query::<(Entity, &Zone)>();
        query
            .iter(&self.world)
            .map(|(e, z)| (e, z.clone()))
            .collect()
    }

    // ========================================================================
    // Direct ECS Access
    // ========================================================================

    /// Get direct access to the underlying bevy_ecs World.
    ///
    /// Use this for advanced queries not covered by the BoardWorld API.
    pub fn ecs(&self) -> &World {
        &self.world
    }

    /// Get mutable access to the underlying bevy_ecs World.
    ///
    /// Use this for advanced operations not covered by the BoardWorld API.
    pub fn ecs_mut(&mut self) -> &mut World {
        &mut self.world
    }

    // ========================================================================
    // Serialization Helpers
    // ========================================================================

    /// Clear all entities and reset resources.
    pub fn clear(&mut self) {
        self.world.clear_entities();
        self.world.insert_resource(SpatialIndex::new());
        self.world.insert_resource(NetRegistry::new());
        self.board_entity = None;
    }
}

impl Default for BoardWorld {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_new_world_is_empty() {
        let mut world = BoardWorld::new();
        assert!(world.is_empty());
        assert_eq!(world.component_count(), 0);
        assert_eq!(world.net_count(), 0);
    }

    #[test]
    fn test_set_board() {
        let mut world = BoardWorld::new();
        let board = world.set_board(
            "TestBoard".to_string(),
            (Nm::from_mm(100.0), Nm::from_mm(80.0)),
            4,
        );

        assert_eq!(world.board_entity(), Some(board));
        assert_eq!(world.board_name(), Some("TestBoard"));

        let (size, layers) = world.board_info().unwrap();
        assert_eq!(size.width, Nm::from_mm(100.0));
        assert_eq!(size.height, Nm::from_mm(80.0));
        assert_eq!(layers.count, 4);
    }

    #[test]
    fn test_spawn_component() {
        let mut world = BoardWorld::new();
        let r1 = world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        assert_eq!(world.component_count(), 1);
        assert_eq!(world.get::<RefDes>(r1).map(|r| r.as_str()), Some("R1"));
        assert_eq!(world.get::<Value>(r1).map(|v| v.as_str()), Some("10k"));
    }

    #[test]
    fn test_intern_net() {
        let mut world = BoardWorld::new();

        let vcc = world.intern_net("VCC");
        let gnd = world.intern_net("GND");
        let vcc2 = world.intern_net("VCC");

        assert_eq!(vcc, vcc2);
        assert_ne!(vcc, gnd);
        assert_eq!(world.net_name(vcc), Some("VCC"));
        assert_eq!(world.net_count(), 2);
    }

    #[test]
    fn test_find_by_refdes() {
        let mut world = BoardWorld::new();

        let r1 = world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        let r2 = world.spawn_component(
            RefDes::new("R2"),
            Value::new("4.7k"),
            Position::from_mm(20.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        assert_eq!(world.find_by_refdes("R1"), Some(r1));
        assert_eq!(world.find_by_refdes("R2"), Some(r2));
        assert_eq!(world.find_by_refdes("R3"), None);
    }

    #[test]
    fn test_spatial_index() {
        let mut world = BoardWorld::new();

        // Spawn some components at known positions
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.spawn_component(
            RefDes::new("R2"),
            Value::new("10k"),
            Position::from_mm(50.0, 50.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Rebuild with simple 1mm x 1mm bounds
        world.rebuild_spatial_index(|_| {
            Rect::from_center_size(Point::ORIGIN, (Nm::from_mm(1.0), Nm::from_mm(1.0)))
        });

        // Query near R1
        let found = world.query_region(Rect::from_points(
            Point::from_mm(9.0, 9.0),
            Point::from_mm(11.0, 11.0),
        ));
        assert_eq!(found.len(), 1);

        // Query near R2
        let found = world.query_region(Rect::from_points(
            Point::from_mm(49.0, 49.0),
            Point::from_mm(51.0, 51.0),
        ));
        assert_eq!(found.len(), 1);

        // Query covering both
        let found = world.query_region(Rect::from_points(
            Point::from_mm(0.0, 0.0),
            Point::from_mm(100.0, 100.0),
        ));
        assert_eq!(found.len(), 2);

        // Query empty area
        let found = world.query_region(Rect::from_points(
            Point::from_mm(200.0, 200.0),
            Point::from_mm(300.0, 300.0),
        ));
        assert!(found.is_empty());
    }

    #[test]
    fn test_clear() {
        let mut world = BoardWorld::new();

        world.set_board("Test".to_string(), (Nm::from_mm(100.0), Nm::from_mm(100.0)), 2);
        world.intern_net("VCC");
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.clear();

        assert!(world.is_empty());
        assert_eq!(world.board_entity(), None);
        assert_eq!(world.net_count(), 0);
    }

    #[test]
    fn test_components_iterator() {
        let mut world = BoardWorld::new();

        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.spawn_component(
            RefDes::new("C1"),
            Value::new("100nF"),
            Position::from_mm(20.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        let components = world.components();
        assert_eq!(components.len(), 2);
    }
}

//! Trace and via components for routing.
//!
//! These components represent copper traces and vias on the PCB.
//! Traces are polyline paths connecting pads, while vias are
//! drill holes that connect copper on different layers.
//!
//! # Architecture
//!
//! - [`TraceSegment`] - A single line segment (start to end point)
//! - [`Trace`] - A polyline path composed of segments, belonging to a net
//! - [`Via`] - A drill hole connecting layers, with annular ring
//! - [`TraceSource`] - Enum indicating if trace was manual or autorouted
//!
//! # Example
//!
//! ```
//! use cypcb_world::components::trace::{Trace, TraceSegment, TraceSource, Via};
//! use cypcb_world::{NetId, Layer};
//! use cypcb_core::{Nm, Point};
//!
//! // Create a trace with two segments
//! let segments = vec![
//!     TraceSegment::new(Point::from_mm(0.0, 0.0), Point::from_mm(5.0, 0.0)),
//!     TraceSegment::new(Point::from_mm(5.0, 0.0), Point::from_mm(5.0, 5.0)),
//! ];
//!
//! let trace = Trace {
//!     segments,
//!     width: Nm::from_mm(0.2),
//!     layer: Layer::TopCopper,
//!     net_id: NetId::new(0),
//!     locked: false,
//!     source: TraceSource::Manual,
//! };
//!
//! assert_eq!(trace.segments.len(), 2);
//! ```

use bevy_ecs::prelude::*;
use serde::{Deserialize, Serialize};

use cypcb_core::{Nm, Point};

use crate::components::electrical::NetId;
use crate::components::physical::Layer;

/// A single line segment of a trace (from start to end point).
///
/// TraceSegment is not a component - it's a data structure used within [`Trace`].
/// Each segment represents a straight line between two points.
///
/// # Example
///
/// ```
/// use cypcb_world::components::trace::TraceSegment;
/// use cypcb_core::Point;
///
/// let seg = TraceSegment::new(
///     Point::from_mm(0.0, 0.0),
///     Point::from_mm(10.0, 5.0),
/// );
///
/// // Calculate segment length
/// let length = seg.length();
/// assert!(length.0 > 0);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct TraceSegment {
    /// Start point of the segment.
    pub start: Point,
    /// End point of the segment.
    pub end: Point,
}

impl TraceSegment {
    /// Create a new trace segment from start to end point.
    #[inline]
    pub fn new(start: Point, end: Point) -> Self {
        TraceSegment { start, end }
    }

    /// Calculate the length of this segment in nanometers.
    ///
    /// Uses Euclidean distance formula: sqrt((x2-x1)^2 + (y2-y1)^2)
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::TraceSegment;
    /// use cypcb_core::{Nm, Point};
    ///
    /// // Horizontal segment, 10mm long
    /// let seg = TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(10.0, 0.0),
    /// );
    /// assert_eq!(seg.length(), Nm::from_mm(10.0));
    ///
    /// // Vertical segment, 5mm long
    /// let seg2 = TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(0.0, 5.0),
    /// );
    /// assert_eq!(seg2.length(), Nm::from_mm(5.0));
    /// ```
    pub fn length(&self) -> Nm {
        let dx = self.end.x.0 - self.start.x.0;
        let dy = self.end.y.0 - self.start.y.0;

        // Use i128 to prevent overflow during squared calculation
        let dx_squared = (dx as i128) * (dx as i128);
        let dy_squared = (dy as i128) * (dy as i128);

        // sqrt of sum, rounded to nearest nanometer
        let sum = dx_squared + dy_squared;
        let length = (sum as f64).sqrt() as i64;

        Nm(length)
    }

    /// Get the midpoint of this segment.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::TraceSegment;
    /// use cypcb_core::Point;
    ///
    /// let seg = TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(10.0, 10.0),
    /// );
    /// let mid = seg.midpoint();
    /// assert_eq!(mid, Point::from_mm(5.0, 5.0));
    /// ```
    pub fn midpoint(&self) -> Point {
        Point::new(
            Nm((self.start.x.0 + self.end.x.0) / 2),
            Nm((self.start.y.0 + self.end.y.0) / 2),
        )
    }
}

/// Indicates whether a trace was created manually or by an autorouter.
///
/// This is used to track the origin of traces for debugging and
/// to potentially apply different editing behaviors.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Serialize, Deserialize)]
pub enum TraceSource {
    /// Trace was manually defined in the DSL.
    #[default]
    Manual,
    /// Trace was generated by the autorouter.
    Autorouted,
}

/// A copper trace connecting pads on a PCB.
///
/// Traces are polyline paths composed of one or more [`TraceSegment`]s.
/// Each trace belongs to a specific net and has a fixed width and layer.
///
/// # Fields
///
/// - `segments`: The polyline path as a vector of segments
/// - `width`: Trace width in nanometers
/// - `layer`: Which copper layer the trace is on
/// - `net_id`: Which net this trace belongs to
/// - `locked`: If true, autorouter should not modify this trace
/// - `source`: Whether trace was manual or autorouted
///
/// # Example
///
/// ```
/// use cypcb_world::components::trace::{Trace, TraceSegment, TraceSource};
/// use cypcb_world::{NetId, Layer};
/// use cypcb_core::{Nm, Point};
///
/// let trace = Trace {
///     segments: vec![
///         TraceSegment::new(Point::from_mm(0.0, 0.0), Point::from_mm(10.0, 0.0)),
///     ],
///     width: Nm::from_mm(0.2),
///     layer: Layer::TopCopper,
///     net_id: NetId::new(0),
///     locked: true,
///     source: TraceSource::Manual,
/// };
///
/// assert!(trace.locked);
/// assert_eq!(trace.total_length(), Nm::from_mm(10.0));
/// ```
#[derive(Component, Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Trace {
    /// The polyline path as a vector of connected segments.
    pub segments: Vec<TraceSegment>,
    /// Trace width in nanometers.
    pub width: Nm,
    /// Which copper layer this trace is on.
    pub layer: Layer,
    /// The net this trace belongs to.
    pub net_id: NetId,
    /// If true, autorouter should not modify this trace.
    pub locked: bool,
    /// Origin of this trace (manual or autorouted).
    pub source: TraceSource,
}

impl Trace {
    /// Create a new trace with default values.
    ///
    /// Creates an empty trace on the top copper layer with 0.2mm width.
    ///
    /// # Arguments
    ///
    /// * `net_id` - The net this trace belongs to
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::Trace;
    /// use cypcb_world::NetId;
    ///
    /// let trace = Trace::new(NetId::new(0));
    /// assert!(trace.segments.is_empty());
    /// assert!(!trace.locked);
    /// ```
    pub fn new(net_id: NetId) -> Self {
        Trace {
            segments: Vec::new(),
            width: Nm::from_mm(0.2), // Default 0.2mm trace width
            layer: Layer::TopCopper,
            net_id,
            locked: false,
            source: TraceSource::Manual,
        }
    }

    /// Add a segment to this trace.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::{Trace, TraceSegment};
    /// use cypcb_world::NetId;
    /// use cypcb_core::Point;
    ///
    /// let mut trace = Trace::new(NetId::new(0));
    /// trace.add_segment(TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(5.0, 0.0),
    /// ));
    /// assert_eq!(trace.segments.len(), 1);
    /// ```
    pub fn add_segment(&mut self, segment: TraceSegment) {
        self.segments.push(segment);
    }

    /// Calculate the total length of this trace.
    ///
    /// Sums the lengths of all segments.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::{Trace, TraceSegment};
    /// use cypcb_world::NetId;
    /// use cypcb_core::{Nm, Point};
    ///
    /// let mut trace = Trace::new(NetId::new(0));
    /// trace.add_segment(TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(10.0, 0.0),
    /// ));
    /// trace.add_segment(TraceSegment::new(
    ///     Point::from_mm(10.0, 0.0),
    ///     Point::from_mm(10.0, 5.0),
    /// ));
    ///
    /// // Total: 10mm + 5mm = 15mm
    /// assert_eq!(trace.total_length(), Nm::from_mm(15.0));
    /// ```
    pub fn total_length(&self) -> Nm {
        let total: i64 = self.segments.iter().map(|s| s.length().0).sum();
        Nm(total)
    }

    /// Get the start point of this trace (first segment start).
    ///
    /// Returns `None` if the trace has no segments.
    pub fn start_point(&self) -> Option<Point> {
        self.segments.first().map(|s| s.start)
    }

    /// Get the end point of this trace (last segment end).
    ///
    /// Returns `None` if the trace has no segments.
    pub fn end_point(&self) -> Option<Point> {
        self.segments.last().map(|s| s.end)
    }

    /// Check if this trace is empty (has no segments).
    pub fn is_empty(&self) -> bool {
        self.segments.is_empty()
    }

    /// Get the number of segments in this trace.
    pub fn segment_count(&self) -> usize {
        self.segments.len()
    }
}

/// A via connecting copper layers through a drill hole.
///
/// Vias are plated through-holes that connect traces on different
/// copper layers. They have a drill diameter and an outer diameter
/// (annular ring).
///
/// # Fields
///
/// - `position`: Center position of the via
/// - `drill`: Drill hole diameter in nanometers
/// - `outer_diameter`: Total via diameter including annular ring
/// - `start_layer`: Upper layer connection
/// - `end_layer`: Lower layer connection
/// - `net_id`: Which net this via belongs to
/// - `locked`: If true, autorouter should not modify this via
///
/// # Example
///
/// ```
/// use cypcb_world::components::trace::Via;
/// use cypcb_world::{NetId, Layer};
/// use cypcb_core::{Nm, Point};
///
/// let via = Via {
///     position: Point::from_mm(5.0, 5.0),
///     drill: Nm::from_mm(0.3),
///     outer_diameter: Nm::from_mm(0.6),
///     start_layer: Layer::TopCopper,
///     end_layer: Layer::BottomCopper,
///     net_id: NetId::new(0),
///     locked: false,
/// };
///
/// assert_eq!(via.annular_ring(), Nm::from_mm(0.15));
/// ```
#[derive(Component, Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Via {
    /// Center position of the via.
    pub position: Point,
    /// Drill hole diameter in nanometers.
    pub drill: Nm,
    /// Total via diameter including annular ring.
    pub outer_diameter: Nm,
    /// Upper layer connection.
    pub start_layer: Layer,
    /// Lower layer connection.
    pub end_layer: Layer,
    /// The net this via belongs to.
    pub net_id: NetId,
    /// If true, autorouter should not modify this via.
    pub locked: bool,
}

impl Via {
    /// Create a new via with default sizes.
    ///
    /// Creates a via connecting top and bottom copper with:
    /// - 0.3mm drill diameter
    /// - 0.6mm outer diameter
    ///
    /// # Arguments
    ///
    /// * `position` - Center position of the via
    /// * `net_id` - The net this via belongs to
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::Via;
    /// use cypcb_world::NetId;
    /// use cypcb_core::Point;
    ///
    /// let via = Via::new(Point::from_mm(10.0, 10.0), NetId::new(0));
    /// assert!(!via.locked);
    /// ```
    pub fn new(position: Point, net_id: NetId) -> Self {
        Via {
            position,
            drill: Nm::from_mm(0.3),
            outer_diameter: Nm::from_mm(0.6),
            start_layer: Layer::TopCopper,
            end_layer: Layer::BottomCopper,
            net_id,
            locked: false,
        }
    }

    /// Calculate the annular ring width (distance from drill edge to via edge).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::Via;
    /// use cypcb_world::NetId;
    /// use cypcb_core::{Nm, Point};
    ///
    /// let via = Via {
    ///     position: Point::from_mm(0.0, 0.0),
    ///     drill: Nm::from_mm(0.3),
    ///     outer_diameter: Nm::from_mm(0.6),
    ///     start_layer: cypcb_world::Layer::TopCopper,
    ///     end_layer: cypcb_world::Layer::BottomCopper,
    ///     net_id: NetId::new(0),
    ///     locked: false,
    /// };
    ///
    /// // Annular ring = (outer - drill) / 2 = (0.6 - 0.3) / 2 = 0.15mm
    /// assert_eq!(via.annular_ring(), Nm::from_mm(0.15));
    /// ```
    pub fn annular_ring(&self) -> Nm {
        Nm((self.outer_diameter.0 - self.drill.0) / 2)
    }

    /// Check if this via spans all copper layers (through-hole via).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::Via;
    /// use cypcb_world::{NetId, Layer};
    /// use cypcb_core::Point;
    ///
    /// let via = Via::new(Point::from_mm(0.0, 0.0), NetId::new(0));
    /// assert!(via.is_through_hole()); // Default is top-to-bottom
    /// ```
    pub fn is_through_hole(&self) -> bool {
        self.start_layer == Layer::TopCopper && self.end_layer == Layer::BottomCopper
    }
}

