    /// Convert to a bit mask value for layer sets.
    ///
    /// The bit positions are:
    /// - 0: TopCopper
    /// - 1: BottomCopper
    /// - 2-31: Inner(0-29)
    /// - Other layers don't have mask bits (return 0)
    pub fn to_copper_mask(&self) -> u32 {
        match self {
            Layer::TopCopper => 1 << 0,
            Layer::BottomCopper => 1 << 1,
            Layer::Inner(n) if *n < 30 => 1 << (2 + *n),
            _ => 0,
        }
    }
